const paymentsPriorNavigate=navigate;navigate=function(target){if(target==='marketplace34'){bank43.tab='orders';target='settlements';}return paymentsPriorNavigate(target==='bank43'?'settlements':target);};
function bank43Page(){
 if(!ERP.access?.permissions?.includes('finance'))return bank43OperationsPage(false,true);
 const engine=ERP.engines.payments,rows=engine.paymentRows(state,bank43),s=engine.paymentSummary(rows),ledger=state.settlementLedger&&!state.settlementLedger.restricted?state.settlementLedger:null;
 const scopeSummary=bank43.status==='all'?s:engine.paymentSummary(engine.paymentRows(state,{...bank43,status:'all'}));
 const pages=Math.max(1,Math.ceil(rows.length/25));bank43.page=Math.max(1,Math.min(bank43.page,pages));const page=rows.slice((bank43.page-1)*25,bank43.page*25);
 const coverage=(n,total)=>`${n} de ${total} ventas`,metric=(label,value,note,tone='sales',vector='bag')=>`<article class="pay-metric ${tone}"><div class="pay-metric-heading"><i>${icon(vector)}</i><span>${label}</span></div><strong>${value}</strong><small>${note}</small></article>`;
 const brandNames=[...new Set([...markets,...state.orders.map(o=>o.market)])].filter(m=>m!=='T1 Comercios');
 const dates=`${bank43.from?'Desde '+esc(bank43.from):'Todo el historial'}${bank43.to?' · hasta '+esc(bank43.to):''}`;
 return `<div class="pay-center">${pageHead('FINANZAS / MARKETPLACES','Conciliación de pagos','Tus ventas, la comisión cobrada y el dinero recibido, en un solo lugar.',`<button class="btn" data-bank43="cheque">${icon('upload')} Subir documento de pago del market</button><button class="btn primary" data-bank43="statement">${icon('upload')} Subir estado de cuenta bancario</button>`)}
 <section class="pay-channel-section" aria-labelledby="pay-channel-title"><div class="pay-section-heading"><div><h2 id="pay-channel-title">Elige el marketplace</h2><p>Consulta todas las ventas o enfócate en un canal.</p></div><button class="btn text" data-bank43="help">Cómo se concilia ${icon('info')}</button></div><div class="pay-channels" role="group" aria-label="Elegir marketplace">${['all',...brandNames].map(m=>{const count=m==='all'?state.orders.length:state.orders.filter(o=>o.market===m).length;return `<button class="pay-channel ${bank43.market===m?'active':''}" data-pay-market="${esc(m)}" aria-pressed="${bank43.market===m}">${m==='all'?`<span class="pay-all-logo">${icon('layers')}</span>`:MarketUI.logo(m,'lg')}<strong>${m==='all'?'Todos los markets':esc(m)}</strong><span>${count} ventas</span>${bank43.market===m?'<b class="pay-channel-check">✓</b>':''}</button>`;}).join('')}</div></section>
 <section class="pay-filters panel" aria-label="Buscar y filtrar ventas"><label class="field-search">${icon('search')}<input id="bank43-query" aria-label="Buscar venta o cheque" placeholder="Pedido, SICAR, producto, SKU o cheque…" value="${esc(bank43.query)}"></label><label>Estado<select id="bank43-status" aria-label="Estado de conciliación">${[['all','Todas las ventas'],['confirmed','Conciliadas'],['pending','Pagos pendientes'],['unpaid','Sin depósito registrado'],['older-unpaid','Sin depósito · posteriores conciliadas'],['favorable','Diferencias a favor'],['shortfall','Diferencias en contra'],['cancelled','Canceladas sin reembolso'],['refunded','Reembolsadas'],['compensated','Con compensaciones']].map(([v,l])=>`<option value="${v}" ${bank43.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Documental desde<input type="date" id="pay-from" value="${esc(bank43.from||'')}"></label><label>Documental hasta<input type="date" id="pay-to" value="${esc(bank43.to||'')}"></label><button class="btn" data-bank43="clear">Limpiar filtros</button></section>
 <div class="pay-section-heading pay-summary-heading"><div><h2>Resumen de ${bank43.market==='all'?'todos los marketplaces':esc(bank43.market)}</h2><p>${s.count} ventas · ${dates} · las métricas respetan todos los filtros.</p></div><button class="btn" data-bank43="export">${icon('download')} Exportar ventas</button></div>
 <section class="pay-unpaid-overview" aria-label="Ventas sin depósito registrado"><div>${icon('alert')}<strong>Ventas sin depósito registrado</strong><small>Canal, búsqueda y fechas actuales · sin filtro de estado</small></div><button class="btn" data-pay-status="unpaid"><b>${scopeSummary.unpaidCount}</b> ventas · ${money(scopeSummary.unpaidEstimatedCents)} estimados</button><button class="btn ${scopeSummary.olderUnpaidCount?'pay-review-button':''}" data-pay-status="older-unpaid"><b>${scopeSummary.olderUnpaidCount}</b> con ventas posteriores ya conciliadas</button><p>Estas últimas requieren seguimiento: se detectó un pago bancario de una venta posterior del mismo market. Esto no confirma vencimiento ni falta de pago.</p></section>
 ${bank43.status==='confirmed'&&scopeSummary.pendingCount?`<div class="info-box pay-filter-explainer">El filtro <strong>Conciliadas</strong> excluye las ventas pendientes: por eso aquí el saldo por conciliar es cero. Fuera de este filtro hay <strong>${scopeSummary.pendingCount} ventas pendientes · ${money(scopeSummary.pendingCents)}</strong>, con el mismo canal, búsqueda y fechas.<button class="btn small" data-pay-status="pending">Ver pendientes</button></div>`:''}
 <section class="pay-metric-groups" aria-label="Resumen financiero ordenado por concepto">
 <div class="pay-metric-group"><h3>Ventas</h3>${metric('Venta bruta',money(s.grossCents),`${s.count} ventas · antes de cancelaciones y reembolsos`,'sales','bag')}${metric('Venta efectiva',money(s.effectiveCents),'Excluye canceladas y reembolsadas','sales','check')}</div>
 <div class="pay-metric-group"><h3>Depósitos</h3>${metric('Depósito neto estimado',s.estimateCount?money(s.estimatedCents):'Por estimar',coverage(s.estimateCount,s.count)+' con estimación; canceladas en cero','deposits','calculator')}${metric('Depósito recibido efectivo',money(s.depositCents),`${s.depositCount} ventas con depósito registrado · ${s.manualCount} manuales`,'deposits','wallet')}<details class="pay-comparison-basis"><summary>¿Por qué lo recibido puede superar al estimado?</summary><p>La estimación usa la comisión configurada en la calculadora. Si la comisión inferida de los pagos es menor, se recibe más de lo estimado. Ese excedente puede superar el importe de las ventas pendientes.</p><span>Recibido en este filtro: ${money(s.depositCents)}<br>Estimado en este filtro: ${money(s.estimatedCents)}</span><small>Estos totales abarcan coberturas distintas. Las diferencias a favor y en contra comparan únicamente las mismas ventas activas con pago completo.</small></details></div>
 <div class="pay-metric-group"><h3>Utilidad</h3>${metric('Utilidad estimada',s.estimatedProfitCount?money(s.estimatedProfitCents):'Por calcular',coverage(s.estimatedProfitCount,s.count)+' con costo y envío calculables','profit','calculator')}${metric('Utilidad efectiva',s.realProfitCount?money(s.realProfitCents):'Por calcular',`${s.realProfitCount} de ${s.depositCount} depósitos con costo y envío conocidos${s.realProfitCount<s.depositCount?' · total parcial':''}`,'profit','arrowup')}</div>
 <div class="pay-metric-group"><h3>Cancelaciones y devoluciones</h3>${metric('Canceladas sin reembolso',money(s.cancelledCents),`${s.cancelledCount} ventas · excluidas del saldo por conciliar`,'cancelled','close')}${metric('Reembolsadas',money(s.refundedCents),`${s.refundedCount} ventas · importe bruto asociado; consulta los débitos`,'refunds','refresh')}</div>
 <div class="pay-metric-group"><h3>Conciliación</h3>${metric('Saldo por conciliar',money(s.pendingCents),`${s.pendingCount} ventas pendientes${s.pendingUnknown?' · '+s.pendingUnknown+' sin estimación, fuera del importe':''}`,'pending','clock')}${metric('Diferencias a favor',s.comparisonCount?money(s.favorableCents):'Sin comparación',`${s.favorableCount} ventas · recibido superior al estimado`,'profit','arrowup')}${metric('Diferencias en contra',s.comparisonCount?money(s.shortfallCents):'Sin comparación',`${s.shortfallCount} ventas · recibido inferior al estimado${s.roundingShortfallCount?' · '+s.roundingShortfallCount+' diferencias de $0.01':''}`,'refunds','alert')}<div class="pay-comparison-basis"><strong>Base comparable: ${s.comparisonCount} ventas activas con pago completo</strong><span>Estimado ${money(s.comparableEstimatedCents)} · Recibido ${money(s.comparableReceivedCents)}</span><b>Neto de diferencias: ${s.differenceCents>0?'+':''}${money(s.differenceCents)}</b><small>A favor menos en contra. Excluye ventas sin depósito, pagos parciales, cancelaciones y reembolsos. Los remanentes frente al modelo requieren revisar comisión y deducciones; no prueban un cobro indebido.</small><div><button class="btn small" data-pay-status="favorable">Ver a favor</button><button class="btn small" data-pay-status="shortfall">Ver en contra</button></div></div></div>
 <div class="pay-metric-group"><h3>Documentos de pago</h3>${metric('Pago según documentos',money(s.documentaryCents),`${s.documentaryCount} ventas con documento de Sears o Sanborns`,'evidence','shield')}<p class="pay-metric-guide">Cada columna reúne un concepto. Estimaciones, depósitos registrados y evidencia documental conservan su propia cobertura.</p></div>
 </section>
 <div class="pay-proof-strip"><span>${icon('shield')} ${s.confirmedCount} ventas conciliadas en este filtro</span>${ledger?`<span><strong>${ledger.cheques.filter(c=>c.status==='reconciled').length} / ${ledger.cheques.length} cheques</strong> cotejados con banco</span><span>${ledger.statements.length} estados de cuenta protegidos</span>`:''}<button class="btn text" data-bank43="pricing-config">Reglas y tasas ${icon('layers')}</button></div>
 ${pageTabs([['orders','Ventas y comisiones'],['cheques','Documentos de pago'],['bank','Estados de cuenta'],['batch','Lotes y deducciones']],bank43.tab,'data-bank43-tab')}
 ${bank43.tab==='orders'?`<section class="panel pay-sales"><div class="pay-table-heading"><div><h2>Ventas del marketplace</h2><p>Más recientes primero · fecha documental · ${rows.length} resultados</p></div><span>Estimación y resultado efectivo con comisión y retenciones</span></div>${bank43SalesTable(page,ledger)}<div class="pay-mobile-sales">${page.map(r=>bank43MobileSale(r,ledger)).join('')}</div>${!page.length?'<div class="bank43-empty">No hay ventas con estos filtros.</div>':''}<div class="table-footer"><span>${rows.length} ventas · página ${bank43.page} de ${pages}</span><div class="pager"><button class="btn small" data-bank43-page="${bank43.page-1}" ${bank43.page<=1?'disabled':''}>Anterior</button><button class="btn small" data-bank43-page="${bank43.page+1}" ${bank43.page>=pages?'disabled':''}>Siguiente</button></div></div></section>`:bank43.tab==='operations'?bank43OperationsPage():bank43.tab==='batch'?window.rec28Embedded?.({market:bank43.market,from:bank43.from,to:bank43.to,q:bank43.query,status:bank43.status})||'':bank43Documents(ledger,rows)}
 <p class="pay-footnote">El depósito confirma el neto recibido. La comisión se infiere del documento de pago y sus ajustes; cuando la retención es estimada, el porcentaje permanece preliminar. El cotejo OCR automático de pagos está disponible para Sears y Sanborns.</p></div>`;
}
function bank43Percent(n){return n==null?'Por identificar':(n*100).toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2})+'%';}
function bank43Commission(r){const c=r.actualCommission;return `<div class="pay-commission ${c.rate==null?'unknown':c.quality==='estimated-tax'?'preliminary':''}"><strong>${bank43Percent(c.rate)}</strong><span>${c.amountCents==null?'Sin desglose del market':money(c.amountCents)}</span><small title="${esc(c.note)}">${esc(c.label)}</small><small class="pay-configured">Calculadora: ${bank43Percent(r.expectedRate)}</small></div>`;}

function bank43Thumbnail(o){const p=state.products.find(p=>p.sku===o.items?.[0]?.sku),img=p?.images?.find(i=>i.primary)||p?.images?.[0];return img?.url?`<img class="pay-product-image" src="${esc(img.url)}" alt="" loading="lazy">`:'';}


function bank43Documents(ledger,rows){if(!ledger)return '<section class="panel bank43-empty"><h2>Documentos y cotejo bancario</h2><p>Los comprobantes Sears y Sanborns del Excel V43 están en Laboratorio V43. Las operaciones y lotes de este espacio se conservan en la pestaña Lotes y deducciones.</p></section>';const ids=new Set(rows.map(r=>r.order.id)),cheques=ledger.cheques.filter(c=>(bank43.market==='all'||c.market===bank43.market)&&c.lines.some(l=>ids.has(l.orderId))).sort((a,b)=>b.date.localeCompare(a.date)),transactions=ledger.transactions.filter(t=>bank43.market==='all'||t.market===bank43.market).sort((a,b)=>b.date.localeCompare(a.date));return bank43.tab==='cheques'?`<section class="panel pay-documents"><div class="pay-table-heading"><div><h2>Documentos de pago</h2><p>${cheques.length} cheques relacionados con las ventas del filtro · más recientes primero</p></div><button class="btn small" data-bank43="config">Reglas de cotejo</button></div><div class="pay-document-grid">${cheques.map(c=>`<article><div>${marketTag(c.market)}${bank43Status(c)}</div><h3>Cheque ${esc(c.number)}</h3><div class="pay-document-concepts">${[...new Set(c.lines.filter(l=>ids.has(l.orderId)).map(l=>ERP.engines.payments.documentMovement(l).label))].map(label=>`<span>${esc(label)}</span>`).join('')}</div><span>${esc(c.date)} · ${c.lines.length} partidas</span><small class="subtext">Total del cheque, que puede incluir otras ventas</small><strong>${money(c.totalCents)}</strong><div>${bank43SourceLink(c)}<button class="btn small" data-bank43-cheque="${esc(c.id)}">Ver partidas y depósito</button></div></article>`).join('')||'<p>No hay documentos de pago relacionados con este filtro.</p>'}</div></section>`:`<section class="panel pay-documents"><div class="pay-table-heading"><div><h2>Estados de cuenta bancarios</h2><p>Originales protegidos · abonos y referencias del canal seleccionado</p></div></div><div class="bank43-document-list">${[...ledger.statements].sort((a,b)=>String(b.period||b.year).localeCompare(String(a.period||a.year))).map(s=>`<article><div><strong>${esc(ledger.documents.find(d=>d.id===s.id)?.name||'Estado de cuenta bancario')}</strong><span class="subtext">${s.transactionIds.length} abonos identificados · cuenta •••• ${esc(s.accountLast4)}</span></div>${bank43DocLink(s.id,'Abrir estado de cuenta')}</article>`).join('')}</div><div class="pay-table-heading"><h2>Abonos identificados</h2><span>${transactions.length} abonos · incluye históricos sin venta en este Excel</span></div><div class="table-wrap"><table><thead><tr><th>Fecha / canal</th><th>Referencia original</th><th>Depósito</th><th>Cheque</th><th>Evidencia</th></tr></thead><tbody>${transactions.map(t=>`<tr><td>${esc(t.date)}<span class="subtext">${esc(t.market)} · Inbursa</span></td><td>${esc(t.reference)}</td><td>${money(t.amountCents)}</td><td>${esc(t.chequeId||'Sin cheque en este Excel')}</td><td>${bank43DocLink(t.documentId,'Ver estado bancario')}</td></tr>`).join('')}</tbody></table></div>${ledger.statements.flatMap(s=>s.issues||[]).map(i=>`<div class="info-box">${esc(i.date)} · ${esc(i.market)} · ${esc(i.reference)}: ${esc(i.reason)}</div>`).join('')}</section>`;}
function bank43Status(c){const labels={awaiting_ocr:'Pendiente de prueba OCR',documented:'Cheque leído · falta banco',reconciled:'Conciliado con banco',amount_difference:'Diferencia de importe',ambiguous:'Más de un abono posible',review:'Requiere revisión'};return `<span class="bank43-status ${c.status==='reconciled'?'ok':''}">${labels[c.status]||'En revisión'}</span>`;}
function bank43DocLink(id,label){return id?`<a class="btn small" target="_blank" rel="noopener" href="/api/documents/${encodeURIComponent(id)}?workspace=${encodeURIComponent(ERP.workspace)}">${esc(label)}</a>`:'';}
function bank43SourceLink(c){return `<a class="btn small" target="_blank" rel="noopener" href="/api/source-cheque/${encodeURIComponent(c.id)}?workspace=${encodeURIComponent(ERP.workspace)}">Ver documento de pago</a>`;}
function bank43Guide(){return `<div class="bank43-empty"><h2>Prueba con documentos reales</h2><p>Estos dos cheques están reservados para probar la lectura. El depósito se mantiene pendiente hasta cargar su estado de cuenta.</p><div class="bank43-demo-cards">${state.settlementLedger.cheques.filter(c=>state.settlementLedger.demoChequeIds.includes(c.id)).map(c=>`<article><strong>${esc(c.market)} · cheque ${esc(c.number)}</strong><h3>${money(c.totalCents)}</h3><p>${esc(c.date)} · ${c.lines.length} partidas documentales</p>${bank43SourceLink(c)}<button class="btn primary" data-bank43-sample="${esc(c.id)}">Leer este cheque</button></article>`).join('')}</div><p>Después sube los estados Banamex de septiembre y octubre de 2026. Las referencias 0011457 y 0032798 se cotejan con sus cheques, conservando el texto original.</p></div>`;}

function bank43Upload(kind){bank43.pending=null;bank43.queue=[];showModal(`<h2 id="modal-title">${kind==='cheque'?'Subir documento de pago del market':'Subir estado de cuenta bancario'}</h2><p class="modal-subtitle">Puedes seleccionar varios archivos. Se cotejan por separado, conservando cada PDF original y evitando depósitos duplicados. Confirma el periodo impreso, las referencias y los importes.</p><label class="bank43-drop">Seleccionar uno o varios archivos<input id="bank43-file" type="file" multiple accept="application/pdf,image/png,image/jpeg" data-kind="${kind}"></label><label class="bank43-ocr"><input id="bank43-force" type="checkbox"> Forzar OCR para documentos escaneados</label><p id="bank43-progress" role="status" aria-live="polite"></p><div id="bank43-preview"></div><div class="modal-actions"><button class="btn" data-action="close-modal">Cerrar</button><button class="btn primary" id="bank43-save" disabled>Guardar y cotejar</button></div>`);}
async function bank43Read(file,kind){
 if(bank43.reading)return;bank43.reading=true;const workspace=ERP.workspace;document.getElementById('bank43-save').disabled=true;bank43.pending=null;document.getElementById('bank43-preview').innerHTML='';
 try{const read=await window.DocumentReader29.extract(file,p=>{const el=document.getElementById('bank43-progress');if(el)el.textContent=file.name+' · '+p.message;},{layout:true,forceOCR:document.getElementById('bank43-force')?.checked});
  if(ERP.workspace!==workspace)throw new Error('Cambió el espacio durante la lectura. Vuelve a cargar el documento.');
  const engine=ERP.engines.settlements,parsed=kind==='cheque'?engine.linkCheque(state,engine.parseCheque(read.text)):engine.parseBankStatement(read.text,state.config.bankReconciliation);
  bank43.pending={file,kind,text:read.text,extraction:read.extraction,workspace};
  document.getElementById('bank43-preview').innerHTML=kind==='cheque'?`<div class="info-box blue"><strong>${esc(parsed.market)} · cheque ${esc(parsed.number)}</strong><p>${money(parsed.totalCents)} · ${parsed.lines.length} partidas · ${parsed.unresolved.length?'Requieren revisión: '+esc(parsed.unresolved.join(', ')):'Todos los pedidos relacionados'}</p><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Documento</th><th>Tipo</th><th>Importe</th><th>Relación</th></tr></thead><tbody>${parsed.lines.map(line=>`<tr><td>${esc(line.orderNumber)}</td><td>${esc(line.documentNumber)}</td><td>${esc(line.code)}</td><td>${money(line.amountCents)}</td><td>${esc(line.orderId||(["CR","DR"].includes(line.code)?"Retención distribuida":"Por identificar"))}</td></tr>`).join('')}</tbody></table></div><p>El depósito solo se confirmará si existe un abono bancario coincidente.</p></div>`:`<div class="info-box blue"><strong>Banamex · periodo impreso ${esc(parsed.period||parsed.year)} · cuenta •••• ${esc(parsed.accountLast4)}</strong><p>${parsed.transactions.length} abonos Sears/Sanborns identificados · ${parsed.issues.length} requieren revisión</p>${parsed.transactions.map(t=>`<p>${esc(t.date)} · ${esc(t.market)} · Ref. ${esc(t.reference)} · ${money(t.amountCents)}</p>`).join('')}</div>`;
  document.getElementById('bank43-save').disabled=false;document.getElementById('bank43-progress').textContent='Lectura completa · '+(read.extraction==='ocr'?'OCR local. Revisa referencias, fechas e importes antes de guardar el cotejo.':'texto PDF. Revisa los datos reconocidos antes de guardar.')+' '+read.warnings.filter(w=>/Página|confianza/.test(w)).join(' ');
 }catch(error){const el=document.getElementById('bank43-progress');if(el)el.textContent=error.message;toast(error.message,true);}finally{bank43.reading=false;}
}
renderers.bank43=bank43Page;
document.addEventListener('change',e=>{if(e.target.id==='bank43-file'&&e.target.files[0])bank43ReadMany([...e.target.files],e.target.dataset.kind);else if(['pay-from','pay-to'].includes(e.target.id)){bank43[e.target.id==='pay-from'?'from':'to']=e.target.value;bank43.page=1;render();}else if(e.target.id==='bank43-status'){bank43.status=e.target.value;bank43.page=1;render();}else if(e.target.id==='bank43-market'){bank43.market=e.target.value;bank43.page=1;render();}else if(e.target.id==='bank43-scope'){bank43.scope=e.target.value;bank43.page=1;render();}});
document.addEventListener('input',e=>{if(e.target.id!=='bank43-query')return;bank43.query=e.target.value;bank43.page=1;const position=e.target.selectionStart;render();const next=document.getElementById('bank43-query');next.focus();next.setSelectionRange(position,position);});
document.addEventListener('click',async e=>{
 const el=e.target.closest('button');if(!el)return;
 if(el.dataset.payStatus){bank43.status=el.dataset.payStatus;bank43.tab='orders';bank43.page=1;render();return;}
 if(el.dataset.payMarket){bank43.market=el.dataset.payMarket;bank43.page=1;render();return;}
 if(el.dataset.bank43Page){bank43.page=Number(el.dataset.bank43Page);render();return;}
 if(el.dataset.bank43Tab){bank43.tab=el.dataset.bank43Tab;render();return;}
 if(el.dataset.bank43Cheque){bank43Details(state.settlementLedger.cheques.find(c=>c.id===el.dataset.bank43Cheque),el.dataset.payOrderContext);return;}
 if(el.dataset.bank43Order){bank43SaleDetails(el.dataset.bank43Order);return;}
 if(el.dataset.bank43Sample){const id=el.dataset.bank43Sample;bank43Upload('cheque');try{const response=await fetch('/api/source-cheque/'+encodeURIComponent(id)+'?workspace='+ERP.workspace);if(!response.ok)throw new Error('No se pudo abrir el cheque original.');await bank43Read(new File([await response.blob()],id.replace('|','_')+'.pdf',{type:'application/pdf'}),'cheque');}catch(error){toast(error.message,true);}return;}
 if(el.id==='bank43-save'){
  const queue=bank43.queue?.length?bank43.queue:bank43.pending?[bank43.pending]:[];if(!queue.length||bank43.reading)return;el.disabled=true;bank43.reading=true;
  try{for(const p of queue){if(p.saved||p.error)continue;if(p.workspace!==ERP.workspace)throw new Error('Cambió el espacio durante la carga.');document.getElementById('bank43-progress').textContent='Guardando '+p.file.name+'…';const form=new FormData();form.append('file',p.file);const response=await fetch('/api/documents?workspace='+ERP.workspace+'&purpose=settlement',{method:'POST',body:form}),data=await response.json();if(!response.ok)throw new Error(data.error);const result=await ERP.command('settlement.'+p.kind,{documentId:data.document.id,text:p.text,extraction:p.extraction});if(!result.ok)throw new Error(result.error||'No se guardó el cotejo. Reintenta los archivos pendientes.');p.saved=true;}
   bank43.pending=null;document.getElementById('bank43-progress').textContent='Cotejo terminado: '+queue.filter(p=>p.saved).length+' documentos guardados. '+queue.filter(p=>p.error).length+' archivos requieren revisión.';document.getElementById('bank43-preview').innerHTML=queue.map(p=>`<p>${p.saved?'✓':'⚠'} ${esc(p.file.name)} · ${p.saved?'Guardado; los duplicados no generan otro pago':esc(p.error||'Pendiente')}</p>`).join('');render();
  }catch(error){toast(error.message,true);el.disabled=false;}finally{bank43.reading=false;}return;
 }
 const action=el.dataset.bank43;if(!action)return;
 if(action==='clear'){Object.assign(bank43,{query:'',status:'all',from:'',to:'',page:1});render();}
 else if(action==='pricing-config'){navigate('configuration');}
 else if(action==='help'){showModal('<h2 id="modal-title">Del pedido al depósito</h2><p>1. Elige el marketplace y revisa las ventas, de la más reciente a la más antigua.</p><p>2. Sube el documento de pago: sus partidas se relacionan con los pedidos. El PDF queda disponible desde cada venta.</p><p>3. Sube el estado bancario: se cotejan referencia, origen e importe antes de confirmar el depósito.</p><p>4. Revisa la utilidad y la comisión inferida. La calculadora conserva su tarifa independiente; los datos faltantes permanecen identificados.</p><p>El OCR automático de documentos de pago está disponible para Sears y Sanborns. Los demás canales conservan su conciliación por venta y lotes.</p><div class="modal-actions"><button class="btn primary" data-action="close-modal">Entendido</button></div>');}
 else if(action==='workspace'){const picker=document.getElementById('workspace-picker');picker.value='v43';picker.dispatchEvent(new Event('change',{bubbles:true}));}
 else if(['cheque','statement'].includes(action))bank43Upload(action);
 else if(action==='export')bank43Export();
 else if(action==='config'){if(!state.config.bankReconciliation){navigate('configuration');return;}const c={...state.config.bankReconciliation,commissionRate:state.config.commissions['T1 Comercios'][0].rate,vatIncluded:state.config.parameters.t1IncludedVat,vatWithholding:state.config.parameters.vatWithholding,incomeWithholding:state.config.parameters.incomeWithholding};showModal(`<h2 id="modal-title">Reglas de conciliación T1</h2><form id="bank43-config"><div class="form-grid">${[['commissionRate','Comisión esperada'],['vatIncluded','IVA incluido en venta'],['vatWithholding','Retención IVA'],['incomeWithholding','Retención ISR']].map(([key,label])=>ERP.field('bank43-c-'+key,label+' (%)',c[key]*100,'number','step="0.01" min="0" max="99.99" required')).join('')}${ERP.field('bank43-c-dateWindowDays','Ventana de cotejo (días)',c.dateWindowDays,'number','min="0" max="365" required')}${ERP.field('bank43-c-companyRfc','RFC empresa para verificar banco',c.companyRfc,'text','required')}</div><p>El importe cheque/banco debe coincidir exactamente. Cambiar la comisión esperada conserva la evidencia histórica y permite ver su diferencia.</p><div class="modal-actions"><button class="btn primary">Guardar reglas</button></div></form>`);}
});
document.addEventListener('submit',async e=>{if(e.target.id!=='bank43-config')return;e.preventDefault();const config={};for(const k of ['commissionRate','vatIncluded','vatWithholding','incomeWithholding'])config[k]=Number(document.getElementById('bank43-c-'+k).value)/100;config.dateWindowDays=Number(document.getElementById('bank43-c-dateWindowDays').value);config.companyRfc=document.getElementById('bank43-c-companyRfc').value.trim().toUpperCase();if((await ERP.command('settlement.config',{config})).ok)document.getElementById('modal').close();});

async function bank43ReadMany(files,kind){
 if(bank43.reading)return;bank43.queue=[];const previews=[];
 for(const file of files){await bank43Read(file,kind);if(bank43.pending){bank43.queue.push({...bank43.pending});previews.push('<section class="bank43-file-result"><h3>'+esc(file.name)+'</h3>'+document.getElementById('bank43-preview').innerHTML+'</section>');}else{const error=document.getElementById('bank43-progress').textContent;bank43.queue.push({file,error});previews.push('<div class="info-box" role="alert">'+esc(file.name)+': '+esc(error)+'</div>');}}
 bank43.pending=null;document.getElementById('bank43-preview').innerHTML=previews.join('');document.getElementById('bank43-save').disabled=!bank43.queue.some(p=>!p.error);document.getElementById('bank43-progress').textContent=bank43.queue.filter(p=>!p.error).length+' archivos listos para guardar · '+bank43.queue.filter(p=>p.error).length+' requieren revisión.';
}
const bank43PriorOrderDetails=orderDetails;
orderDetails=function(id){bank43PriorOrderDetails(id);const o=state.orders.find(o=>o.id===id),ledger=state.settlementLedger,drawer=document.getElementById('drawer');if(!o||!ledger||ledger.restricted||!['Sears','Sanborns'].includes(o.market)||drawer.hidden)return;drawer.insertAdjacentHTML('beforeend',bank43SaleEvidence(o));};

const bank43PriorSettlements=renderers.settlements;
renderers.settlements=bank43Page;
const bank43PriorPayment=c28Payment;
c28Payment=function(o){if(o.reconciliation?.confirmationSource==='manual')return o.reconciliation.status;if(ERP.engines.payments?.paymentRow(o,state).documentaryRefund)return o.reconciliation?.status==='Conciliada'?'Reembolsada · débito conciliado con banco':'Reembolsada · débito documental por cotejar';return o.reconciliation?.bankProofRequired?(o.reconciliation.status==='Conciliada'?'Pago conciliado con banco':o.reconciliation.status==='Conciliación parcial'?'Pago parcialmente conciliado':o.reconciliation.status==='Cancelada · sin pago esperado'?'Cancelada · sin depósito esperado':'Pendiente de comprobar depósito'):bank43PriorPayment(o);};

function bank43Export(){ERP.downloadCSV('conciliacion-de-pagos',ERP.engines.payments.paymentRows(state,bank43).map(r=>({marketplace:r.order.market,pedido:r.order.number,origen_conciliacion:r.manual?'Manual':r.order.reconciliation?.confirmationSource||'Sin cotejo',fecha_creacion:r.creationDate,fecha_documental:r.documentDate,fecha_venta:r.date,upc:(r.order.items||[]).map(i=>i.upc||'').join('; '),sku:(r.order.items||[]).map(i=>i.sku||'').join('; '),folio_sicar:r.order.sicar,venta_bruta:r.order.totalCents/100,estado_venta:r.financialState,neto_estimado:r.estimate?.netCents==null?'Pendiente':r.estimate.netCents/100,utilidad_estimada:r.estimate?.profitCents==null?'Pendiente':r.estimate.profitCents/100,comision_pago_porcentaje:r.actualCommission.rate==null?'Por identificar':r.actualCommission.rate*100,comision_pago_mxn:r.actualCommission.amountCents==null?'Por identificar':r.actualCommission.amountCents/100,condicion_comision:r.actualCommission.label,comision_calculadora_porcentaje:r.expectedRate==null?'Sin estimar':r.expectedRate*100,cheques:r.order.t1Source?.cheques||'',conceptos_documentales:r.documents.map(d=>d.cheque.number+': '+d.parts.map(p=>p.code+' '+p.label+' '+(p.amountCents/100)).join(' / ')).join('; '),reembolso_documental:r.documentaryRefund?'Sí':'No',compensaciones:r.compensations.map(p=>p.code+' '+p.label+' '+(p.amountCents/100)).join('; '),pago_documental:r.documentaryCents==null?'Pendiente':r.documentaryCents/100,deposito_recibido:r.depositCents==null?'Pendiente':r.depositCents/100,utilidad_deposito:r.realProfitCents==null?'Pendiente':r.realProfitCents/100,diferencia_pago_completo:r.paymentDifferenceCents==null?'No comparable':r.paymentDifferenceCents/100,sin_deposito:r.unpaid?'Sí':'No',venta_posterior_conciliada:r.laterPaidSale?.number||'',fecha_venta_posterior:r.laterPaidSale?.date||'',estado_pago:r.statusLabel})));}
document.addEventListener('click',e=>{const b=e.target.closest('[data-pay-operate]');if(!b)return;bank43ManualModal(b.dataset.payOperate);});

window.rec28Filter=function(filter={}){bank43.market=filter.market&&filter.market!=='Todos'?filter.market:'all';bank43.query=filter.q||'';bank43.from=filter.from||'';bank43.to=filter.to||'';bank43.status=({'Conciliada':'confirmed','Pagos pendientes':'pending'})[filter.status]||'all';bank43.tab='orders';bank43.page=1;navigate('settlements');};
const paymentsPriorFilteredOrders=filteredOrders;
filteredOrders=function(){return ERP.engines.payments?ERP.engines.payments.newestSales(paymentsPriorFilteredOrders()):paymentsPriorFilteredOrders();};

function bank43MovementBadges(r){return `<div class="pay-status-stack"><span class="bank43-status ${r.confirmed?'ok':r.financialState==='cancelled'?'neutral':''}">${esc(r.confirmed?(r.manual?'Conciliada manualmente':'Conciliada'):r.documentaryRefund?'Pendiente de cotejo bancario':r.statusLabel)}</span>${r.laterPaidSale?`<span class="pay-movement-badge pay-unpaid-alert" title="${esc('Pedido posterior '+r.laterPaidSale.number+' · fecha documental '+r.laterPaidSale.date+' · cotejado con banco')}">Sin depósito · venta posterior conciliada</span>`:''}${r.financialState==='refunded'?`<span class="pay-movement-badge refund">Reembolsada${r.documentaryRefund?' · débito documentado':''}</span>`:''}${r.compensations.some(p=>p.kind==='compensation-credit')?'<span class="pay-movement-badge compensation-credit">Compensación a favor</span>':''}${r.compensations.some(p=>p.kind==='compensation-debit')?'<span class="pay-movement-badge compensation-debit">Compensación en contra</span>':''}</div>`;}
function bank43DateText(value){if(!value)return 'Sin fecha registrada';if(/(?:Z|[+-]\d{2}:?\d{2})$/.test(value)){const d=new Date(value);if(Number.isFinite(d.getTime()))return new Intl.DateTimeFormat('es-MX',{timeZone:'America/Mexico_City',dateStyle:'medium',timeStyle:'short'}).format(d);}const m=String(value).match(/^(\d{4})-(\d{2})-(\d{2})(?:T|\s)?(\d{2}:\d{2})?/);return m?`${m[3]}/${m[2]}/${m[1]}${m[4]?' · '+m[4]:''}`:String(value);}
function bank43Dates(r){return `<div class="pay-creation" title="${esc(r.creationDate?'Creación: '+bank43DateText(r.creationDate):'Creación sin registrar')}"><small>${esc(r.dateLabel)}</small><strong>${esc(bank43DateText(r.date))}</strong></div>`;}
function bank43ProductList(o){const items=o.items?.length?o.items:[{name:o.productNames,sku:o.sku,upc:o.upc,qty:o.qty}];return `<div class="pay-products">${items.map(i=>{const p=state.products.find(p=>p.sku===i.sku),sku=i.sku||p?.sku||'',upc=i.upc||p?.upc||'';return `<div class="pay-product-detail"><strong class="pay-product-title">${esc(i.name||p?.name||'Producto por identificar')}</strong><div class="pay-product-identifiers">${sku?(p?`<button type="button" class="pay-sku-link" data-product="${esc(sku)}" aria-label="Consultar producto SKU ${esc(sku)}">SKU <code>${esc(sku)}</code></button>`:`<span>SKU <code>${esc(sku)}</code></span>`):'<span>SKU por identificar</span>'}<span>UPC <code>${esc(upc||'Por identificar')}</code></span>${i.qty!=null?`<span>${esc(i.qty)} unidad${Number(i.qty)===1?'':'es'}</span>`:''}</div></div>`;}).join('')}</div>`;}
function bank43PaymentAmount(n,empty='Por determinar'){return n==null?`<span class="pay-value-pending">${empty}</span>`:money(n);}
function bank43EstimateValues(r){const e=r.estimate;return `<div class="pay-value-pair estimated"><div><small>Depósito neto estimado</small><strong>${bank43PaymentAmount(e?.netCents,'Sin estimación')}</strong></div><div><small>Utilidad estimada</small><strong>${bank43PaymentAmount(e?.profitCents)}</strong></div><p class="pay-deduction-summary">Comisión configurada <b>${bank43Percent(r.expectedRate)}</b> · ${bank43PaymentAmount(e?.commissionCents)}<br>Retenciones estimadas <b>${bank43PaymentAmount(e?e.vatCents+e.incomeCents:null)}</b><span>IVA ${bank43PaymentAmount(e?.vatCents)} · ISR ${bank43PaymentAmount(e?.incomeCents)}</span></p></div>`;}
function bank43EffectiveValues(r){const c=r.actualCommission,t=ERP.engines.payments.paymentRetention(r);return `<div class="pay-value-pair effective"><div><small>Depositado${r.manual?' · manual':r.documents.some(d=>d.hasRefund||d.hasCompensation)?' · neto de movimientos':''}</small><strong>${bank43PaymentAmount(r.depositCents,'Sin depósito registrado')}</strong></div><div><small>Utilidad efectiva</small><strong>${bank43PaymentAmount(r.realProfitCents)}</strong></div><p class="pay-deduction-summary" title="${esc(c.note)}">Comisión inferida <b>${bank43Percent(c.rate)}</b> · ${bank43PaymentAmount(c.amountCents)}<span>${esc(c.label)}</span>${esc(t.label)} <b>${bank43PaymentAmount(t.amountCents)}</b></p></div>`;}
function bank43RowDocuments(r,ledger){return r.documents.length?r.documents.map(d=>{const groups=[...new Map(d.parts.map(p=>[p.kind,p])).values()];return `<div class="pay-document-group"><span>Cheque ${esc(d.cheque.number)}</span>${groups.map(p=>`<button class="pay-document ${p.kind}" data-bank43-cheque="${esc(d.cheque.id)}" data-pay-order-context="${esc(r.order.id)}"><b>${esc(p.label)}</b><small>${esc(d.parts.filter(x=>x.kind===p.kind).map(x=>x.code).join(' / '))} · ${money(d.parts.filter(x=>x.kind===p.kind).reduce((s,x)=>s+x.amountCents,0))}</small></button>`).join('')}</div>`;}).join(''):'<span class="subtext">Sin documento de pago</span>';}
function bank43SalesTable(rows,ledger){return `<div class="table-wrap pay-desktop-sales"><table><thead><tr><th>Fecha documental / venta / producto</th><th>Depósito neto y utilidad estimados</th><th>Depositado y utilidad efectiva</th><th>Documentos de pago y ajustes</th><th>Conciliación</th></tr></thead><tbody>${rows.map(r=>{const o=r.order;return `<tr data-pay-sale="${esc(o.id)}"><td>${bank43Dates(r)}<div class="pay-order-identity">${bank43Thumbnail(o)}<div><button class="row-title" data-order="${esc(o.id)}">Pedido ${esc(o.number)}</button><span class="subtext">${esc(o.market)} · SICAR ${esc(o.sicar||'sin folio')}</span></div></div>${bank43ProductList(o)}<span class="pay-gross-inline">Venta bruta <b>${money(o.totalCents)}</b></span></td><td>${bank43EstimateValues(r)}${r.error?`<small class="pay-error">${esc(r.error)}</small>`:''}</td><td>${bank43EffectiveValues(r)}</td><td>${bank43RowDocuments(r,ledger)}</td><td>${bank43MovementBadges(r)}<div class="pay-row-actions"><button class="btn small" data-bank43-order="${esc(o.id)}">Ver desglose</button><button class="btn small" data-pay-manage="${esc(o.id)}">Conciliar manualmente</button></div></td></tr>`;}).join('')}</tbody></table></div>`;}
function bank43MobileSale(r,ledger){const o=r.order;return `<article class="pay-sale-card" data-pay-sale-mobile="${esc(o.id)}"><div class="pay-sale-head">${marketTag(o.market)}${bank43MovementBadges(r)}</div>${bank43Dates(r)}<div class="pay-mobile-identity"><button class="row-title" data-order="${esc(o.id)}">Pedido ${esc(o.number)}</button><span>Venta bruta <b>${money(o.totalCents)}</b></span></div>${bank43ProductList(o)}<div class="pay-mobile-financials"><section class="pay-estimate-section">${bank43EstimateValues(r)}</section><section class="pay-effective-section">${bank43EffectiveValues(r)}</section></div><section class="pay-sale-actions">${bank43RowDocuments(r,ledger)}<div class="pay-row-actions"><button class="btn small" data-bank43-order="${esc(o.id)}">Ver desglose</button><button class="btn small" data-pay-manage="${esc(o.id)}">Conciliar manualmente</button></div></section></article>`;}

function bank43DocumentEvidence(r){const ledger=state.settlementLedger;return r.documents.length?r.documents.map(d=>{const c=d.cheque;return `<article class="pay-sale-evidence"><div class="pay-document-heading"><strong>${esc(c.market)} · cheque ${esc(c.number)}</strong><span>${esc(bank43DateText(c.date))}</span>${bank43Status(c)}</div><div class="pay-document-parts">${d.parts.map(p=>`<div class="${p.kind}"><span><b>${esc(p.label)}</b><small>${esc(p.code)} · Documento ${esc(p.documentNumber)} · ${esc(p.description)}</small></span><strong>${money(p.amountCents)}</strong></div>`).join('')}${d.taxAdjustmentCents?`<div class="tax"><span>Distribución fiscal CR/DR<small>Retención o restitución distribuida; no es otra compensación ni un reembolso adicional.</small></span><strong>${money(d.taxAdjustmentCents)}</strong></div>`:''}</div><div class="pay-document-net"><span>Efecto neto de este cheque en la venta</span><strong>${bank43PaymentAmount(d.netCents)}</strong></div><p>El banco confirma el total del cheque. El efecto mostrado corresponde únicamente a esta venta.</p><div class="head-actions">${bank43SourceLink(c)}<button class="btn small" data-bank43-cheque="${esc(c.id)}" data-pay-order-context="${esc(r.order.id)}">Ver partidas del cheque</button>${bank43DocLink(ledger.transactions.find(t=>t.id===c.bankTransactionId)?.documentId,'Ver estado de cuenta')}</div></article>`;}).join(''):'<p>Esta venta todavía no tiene documento de pago relacionado.</p>';}
function bank43Details(c,orderId){const order=state.orders.find(o=>o.id===orderId);showModal(`<h2 id="modal-title">${esc(c.market)} · cheque ${esc(c.number)}</h2><p>${esc(bank43DateText(c.date))} · Total del cheque ${money(c.totalCents)} · ${bank43Status(c)}</p>${order?`<p class="info-box blue">Contexto: pedido ${esc(order.number)}. Las partidas de esta venta aparecen resaltadas; el cheque puede incluir otras ventas.</p>`:''}<div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Documento</th><th>Tipo / concepto</th><th>Importe del documento</th><th>Relación</th></tr></thead><tbody>${c.lines.map(l=>{const m=ERP.engines.payments.documentMovement(l);return `<tr class="${l.orderId===orderId?'pay-document-highlight':''}"><td>${esc(l.orderNumber)}</td><td>${esc(l.documentNumber)}</td><td><strong>${esc(l.code)} · ${esc(m.label)}</strong><span class="subtext">${esc(m.description)}</span></td><td>${money(l.amountCents)}</td><td>${esc(l.orderId||(['CR','DR'].includes(l.code)?'Retención distribuida':'Por identificar'))}</td></tr>`;}).join('')}</tbody></table></div><div class="info-box blue spacer-top">LP/NP/NT identifican pagos; LD/ND, débitos por devolución o reembolso; SI completa un pago insuficiente y SV descuenta un exceso. CR/DR se muestran como ajuste fiscal. Un mismo cheque puede incluir distintos conceptos y ventas.</div><div class="modal-actions">${order?`<button class="btn" data-bank43-order="${esc(order.id)}">Volver al desglose de la venta</button>`:''}${bank43SourceLink(c)}${bank43DocLink(c.documentId,'Cheque cargado')}${bank43DocLink(state.settlementLedger.transactions.find(t=>t.id===c.bankTransactionId)?.documentId,'Evidencia bancaria')}<button class="btn" data-action="close-modal">Cerrar</button></div>`);}
function bank43SaleEvidence(o){const r=ERP.engines.payments.paymentRow(o,state);return `<section class="drawer-block bank43-sale-proof"><h3>Documentos de pago, reembolsos y compensaciones</h3>${bank43MovementBadges(r)}<p>Depositado neto: ${bank43PaymentAmount(r.depositCents,'Sin depósito confirmado')}</p>${bank43DocumentEvidence(r)}<button class="btn spacer-top" data-bank43-order="${esc(o.id)}">Ver desglose y utilidad de esta venta</button></section>`;}
function bank43SaleDetails(id){const o=state.orders.find(o=>o.id===id);if(!o)return;const r=ERP.engines.payments.paymentRow(o,state),e=r.estimate,c=r.actualCommission;showModal(`<h2 id="modal-title">Pago de ${esc(o.market)} · ${esc(o.number)}</h2>${bank43Dates(r)}<p class="modal-subtitle">SICAR ${esc(o.sicar||'sin folio')}</p>${bank43MovementBadges(r)}${bank43ProductList(o)}<section class="pay-fee-explanation"><div><small>Comisión cobrada / inferida</small><strong>${bank43Percent(c.rate)} ${c.amountCents==null?'':'· '+money(c.amountCents)}</strong><p>${esc(c.label)}. ${esc(c.note)}</p></div><div><small>Tarifa de calculadora</small><strong>${bank43Percent(r.expectedRate)}</strong><p>Se utiliza para el depósito neto estimado y la utilidad estimada. No confirma lo cobrado por el marketplace.</p></div></section><div class="detail-grid pay-detail-values">${[['Venta bruta',o.totalCents],['Depósito neto estimado',e?.netCents],['Depositado · neto de movimientos',r.depositCents],['Pago neto documental',r.documentaryCents],['Utilidad estimada',e?.profitCents],['Utilidad efectiva',r.realProfitCents],['Costo de mercancía',e?.costCents],['Envío externo',e?.externalShippingCents],['IVA retenido · modelo',e?.vatCents],['ISR retenido · modelo',e?.incomeCents]].map(([label,n])=>`<div><small>${label}</small><strong>${bank43PaymentAmount(n)}</strong></div>`).join('')}</div>${r.error?`<div class="info-box">${esc(r.error)}</div>`:''}${r.realProfitCents==null?'<div class="info-box">La utilidad efectiva queda por determinar cuando falta costo o envío confirmado, o cuando un reembolso requiere revisar mercancía, comisiones y restituciones.</div>':''}<h3 class="spacer-top">Pago original, débitos y compensaciones</h3>${bank43DocumentEvidence(r)}<div class="modal-actions"><button class="btn" data-pay-manage="${esc(id)}">Conciliación manual y opciones avanzadas</button>${!o.reconciliation?.bankProofRequired?`<button class="btn" data-pay-operate="${esc(id)}">Condiciones, depósito y seguimiento</button>`:''}<button class="btn primary" data-action="close-modal">Cerrar</button></div>`);}
window.openPaymentOperations=function(id){bank43ManualModal(id);};
function bank43ManualModal(id){
 const o=state.orders.find(o=>o.id===id);if(!o)return;const r=ERP.engines.payments.paymentRow(o,state),m=o.reconciliation?.manual,finance=ERP.access?.permissions?.includes('finance'),bankLocked=o.reconciliation?.confirmationSource==='bank',closed=!!o.reconciliation?.closure;
 const value=n=>n==null?'':(n/100).toFixed(2);
 showModal(`<h2 id="modal-title">Conciliación manual · ${esc(o.number)}</h2><p class="modal-subtitle">${esc(o.market)} · ${esc(bank43DateText(r.date))} · fecha documental</p>${bank43ProductList(o)}${finance?`<div class="pay-manual-context">${bank43EstimateValues(r)}${bank43EffectiveValues(r)}</div><p class="info-box">Declara el total recibido acumulado de esta venta. Sustituye el registro manual anterior; no se suma al banco ni genera evidencia bancaria. El cotejo documental completo tendrá prioridad.</p>${bankLocked?'<div class="info-box blue">Esta venta ya está cotejada con banco. Su importe está protegido; puedes consultar el desglose y sus documentos.</div>':closed?'<div class="info-box">La conciliación está cerrada. Reábrela con motivo en opciones avanzadas.</div>':`<form id="pay-manual-form" data-order-id="${esc(id)}"><div class="form-grid"><label>Depósito recibido acumulado (MXN)<input name="amount" type="number" min="0" step="0.01" required value="${value(m?.amountCents??r.depositCents)}"></label><label>Fecha del depósito<input name="date" type="date" required value="${esc(m?.date||o.reconciliation?.depositDate||new Intl.DateTimeFormat('en-CA',{timeZone:'America/Mexico_City',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()))}"></label><label>Estado del pago<select name="complete"><option value="true" ${m?.complete!==false?'selected':''}>Completo · conciliar manualmente</option><option value="false" ${m?.complete===false?'selected':''}>Parcial · conservar saldo pendiente</option></select></label><label>Retenciones reales declaradas (MXN)<input name="withholding" type="number" min="0" step="0.01" placeholder="Vacío = estimación, no comprobada" value="${value(m?.withholdingCents)}"></label><label>Envío descontado del depósito (MXN)<input name="shipping" type="number" min="0" step="0.01" placeholder="0 si no se descontó envío" value="${value(m?.shippingCents)}"></label><label class="span-2">Motivo o referencia del registro manual<textarea name="notes" required minlength="5" maxlength="2000" placeholder="Explica cómo comprobaste este pago">${esc(m?.notes||'')}</textarea></label></div><p class="pay-footnote">La comisión se infiere descontando depósito, retención y envío de la venta bruta. Una retención estimada mantiene la comisión como preliminar. Las retenciones tienen sus propias bases y tasas; no se calculan a partir del porcentaje de comisión.</p><div class="modal-actions"><button class="btn primary" type="submit">Guardar conciliación manual</button></div></form>`}${m?`<p class="pay-footnote">Última declaración: ${esc(m.actor)} · ${esc(bank43DateText(m.at))}. ${esc(m.notes)}</p>`:''}`:''}<details class="pay-manual-advanced"><summary>Opciones avanzadas · logística, promociones, fechas, series y cierre</summary>${finance?market34Detail(o):bank43RestrictedOperations(o)}</details><div class="modal-actions"><button class="btn" data-bank43-order="${esc(id)}">Ver desglose y documentos</button><button class="btn" data-action="close-modal">Cerrar</button></div>`);
}
document.addEventListener('submit',async e=>{if(e.target.id!=='pay-manual-form')return;e.preventDefault();const form=e.target,button=form.querySelector('[type="submit"]'),data=new FormData(form),amount=k=>String(data.get(k)||'').trim()===''?null:Math.round(Number(data.get(k))*100);button.disabled=true;try{const result=await ERP.command('payment.manual.save',{orderId:form.dataset.orderId,amountCents:amount('amount'),date:data.get('date'),complete:data.get('complete')==='true',withholdingCents:amount('withholding'),shippingCents:amount('shipping'),notes:data.get('notes')});if(result.ok)bank43ManualModal(form.dataset.orderId);}finally{button.disabled=false;}});

function bank43OperationsPage(embedded=true,restricted=false){
 const list=ERP.engines.payments.newestSales(state.orders.filter(o=>{const q=(bank43.controlQuery||'').toLowerCase();return [o.id,o.number,o.sicar,o.market,o.productNames,...(o.items||[]).map(i=>[i.name,i.sku,i.upc].join(' '))].join(' ').toLowerCase().includes(q);}));
 const selected=state.orders.find(o=>o.id===(bank43.controlId||market34Order))||list[0];if(selected){bank43.controlId=selected.id;market34Order=selected.id;}
 return `${embedded?'':pageHead('OPERACIÓN / CONCILIACIÓN','Gestión de la venta','Logística, promociones, series, fechas y cierre, con los permisos de tu rol.')}<section class="panel pay-operations-selector"><div><h2>Gestión de la venta</h2><p>Las funciones de Control Marketplace ahora están aquí. Las fechas, promociones, cargos, series, IMEI y cierres conservan su historial.</p></div><label class="field-search">${icon('search')}<input id="pay-ops-search" aria-label="Buscar venta para gestionar" placeholder="Pedido, producto, UPC, SKU o folio SICAR" value="${esc(bank43.controlQuery||'')}"></label><label>Venta seleccionada<select id="pay-control-id">${selected&&!list.some(o=>o.id===selected.id)?`<option value="${esc(selected.id)}">${esc(selected.market+' · '+selected.number+' · '+bank43DateText(ERP.engines.payments.saleDate(selected)))}</option>`:''}${list.map(o=>`<option value="${esc(o.id)}" ${o.id===selected?.id?'selected':''}>${esc(o.market+' · '+o.number+' · '+bank43DateText(ERP.engines.payments.saleDate(o)))}</option>`).join('')}</select></label><div class="head-actions"><button class="btn small" data-view="administration">Almacenes, usuarios y roles</button><button class="btn small" data-view="configuration">Reglas y configuración</button>${!restricted?'<button class="btn small" data-bank43-tab="orders">Volver a ventas y comisiones</button>':''}</div></section>${selected?`<section class="panel pay-operational-identity">${bank43Dates(ERP.engines.payments.paymentRow(selected,state))}${bank43ProductList(selected)}<p>Almacén de la venta: <strong>${esc(adminName(selected.warehouseId||'principal'))}</strong></p></section>${restricted?bank43RestrictedOperations(selected):market34Detail(selected)}`:'<section class="panel bank43-empty">No hay ventas para esta búsqueda.</section>'}`;
}
function bank43RestrictedOperations(o){return `<section class="panel bank43-empty"><h2>Operación de ${esc(o.market)} · ${esc(o.number)}</h2><p>Los documentos bancarios y los importes de conciliación requieren permiso de finanzas. Puedes utilizar las operaciones autorizadas para tu rol.</p><div class="head-actions">${o.market==='Liverpool'?market34Button(o,'Promoción y MSI','promotion','sales'):''}${market34Button(o,'Cotejar logística','logistics','finance')}${market34Button(o,'Series e IMEI','identifiers','inventory')}${market34Button(o,'Fechas documentadas','trace','sales')}<button class="btn" data-order="${esc(o.id)}">Ver venta</button></div></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-pay-manage]');if(b)window.openPaymentOperations(b.dataset.payManage);});
document.addEventListener('change',e=>{if(e.target.id==='pay-control-id'){bank43.controlId=e.target.value;market34Order=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id!=='pay-ops-search')return;bank43.controlQuery=e.target.value;const p=e.target.selectionStart;render();const next=document.getElementById('pay-ops-search');next.focus();next.setSelectionRange(p,p);});
